@lru_cache(maxsize=128)
def sha(raw):return hashlib.sha256(raw.replace(b'\r\n',b'\n')).hexdigest()
def fingerprint(v):return hashlib.sha256(json.dumps(v,sort_keys=True,ensure_ascii=True,allow_nan=False,separators=(',',':')).encode()).hexdigest()


def _git(root,*args):
    return _git_raw(root,*args).replace(b'\r\n',b'\n')


def _git_raw(root,*args,input=None):
    result=subprocess.run(['git',*args],cwd=root,input=input,capture_output=True)
    if result.returncode:raise ValueError('Cannot verify M5 history')
    return result.stdout


@lru_cache(maxsize=8)
def _decode(raw,pin):
    v=json.loads(raw)
    if (fingerprint(v)!=pin or set(v)!={'version','baseline_commit','members','publication_authorized','production_intersection','adoption_intersection','frozen_m7_intersection'}
            or v['version']!=1 or v['baseline_commit']!=BASE or set(v['members'])!=MEMBERS
            or v['publication_authorized'] is not False or any(v[k]!=[] for k in ('production_intersection','adoption_intersection','frozen_m7_intersection'))):raise ValueError('Changed exact M5 manifest')
    changed={n for n,b in v['members'].items() if b['before_sha256'] is not None}
    if changed!=set(APPROVED):raise ValueError('Changed M5 predecessor membership')
    for name,(before,after) in APPROVED.items():
        if v['members'][name]!={'before_sha256':before,'sha256':after}:raise ValueError('Changed independently approved M5 successor')
    return v


def manifest():return _decode(regular(ROOT,MANIFEST.relative_to(ROOT).as_posix()).read_bytes(),PIN)


@lru_cache(maxsize=1)
def _baseline_tree():
    # Only immutable objects at the fixed, independently approved BASE are cached.
    raw=_git_raw(ROOT,'ls-tree','-z',BASE,'--',*sorted(MEMBERS))
    if not raw.endswith(b'\0'):raise ValueError('Incomplete M5 predecessor tree')
    entries={}
    for row in raw[:-1].split(b'\0'):
        fields,name=row.split(b'\t',1);name=name.decode('utf8');fields=fields.split()
        if (name not in APPROVED or name in entries or len(fields)!=3 or fields[:2]!=[b'100644',b'blob']
                or len(fields[2])!=40 or any(c not in b'0123456789abcdef' for c in fields[2])):raise ValueError('Changed M5 predecessor tree')
        entries[name]=fields[2]
    if set(entries)!=set(APPROVED):raise ValueError('Changed M5 predecessor membership')
    return tuple(sorted(entries.items()))


@lru_cache(maxsize=1)
def _predecessors():
    entries=_baseline_tree()
    raw=_git_raw(ROOT,'cat-file','--batch',input=b''.join(oid+b'\n' for _,oid in entries))
    values=[];offset=0
    for name,oid in entries:
        end=raw.find(b'\n',offset)
        fields=raw[offset:end].split()
        if end<offset or len(fields)!=3 or fields[:2]!=[oid,b'blob'] or not fields[2].isdigit():raise ValueError('Invalid M5 predecessor batch')
        size=int(fields[2]);start=end+1;end=start+size
        if end>=len(raw) or raw[end:end+1]!=b'\n':raise ValueError('Truncated M5 predecessor batch')
        data=raw[start:end]
        if (hashlib.sha1(b'blob '+str(size).encode()+b'\0'+data).hexdigest().encode()!=oid
                or sha(data)!=APPROVED[name][0]):raise ValueError('Changed M5 predecessor bytes')
        values.append((name,data.replace(b'\r\n',b'\n')));offset=end+1
    if offset!=len(raw):raise ValueError('Unexpected M5 predecessor batch data')
    return tuple(values)


@lru_cache(maxsize=32)
def _old(name):
    if name in APPROVED:return dict(_predecessors())[name]
    return _git(ROOT,'show',BASE+':'+name)


@lru_cache(maxsize=64)
def _baseline_entry(name):
    if name in MEMBERS:
        oid=dict(_baseline_tree()).get(name)
        return b'100644 blob '+oid+b'\t'+name.encode()+b'\n' if oid is not None else b''
    return _git(ROOT,'ls-tree',BASE,'--',name)


@lru_cache(maxsize=32)
def _ancestry(root,head):_git(root,'merge-base','--is-ancestor',BASE,head)


def _physical_paths(root,names):
    from ci.people_readme_maintenance import _regular_files
    # A new lstat of every leaf and shared ancestor on EVERY call. The inherited
    # helper caches path arithmetic only, never filesystem or permission facts.
    return _regular_files(root,names|{MANIFEST.relative_to(ROOT).as_posix()})


def verify_checkout(root=None):
    root=Path(root or ROOT)
    if root.resolve()!=ROOT.resolve():raise ValueError('Foreign M5 policy checkout')
    from ci.phase5_m6_maintenance import verify_checkout as verify_m6, historical_bytes as m6_bytes
    verify_m6(root)
    paths=_physical_paths(root,MEMBERS|ANCHORS)
    value=_decode(paths[MANIFEST.relative_to(ROOT).as_posix()].read_bytes(),PIN)
    from ci.people_colorize_maintenance import _head
    _ancestry(str(root),_head(root))
    collection=collection_adapter().m5_bindings(root)
    for name,binding in value['members'].items():
        actual=m6_bytes(root,name,paths[name].read_bytes())
        if name=='.github/workflows/phase5-m5-validation.yml':
            actual=unicode_adapter().historical_bytes(root,name,actual)
        if name in collection:
            approved,before=collection[name]
            if sha(actual)!=approved:raise ValueError('Changed physical COLLECTION successor: '+name)
            actual=before
        if sha(actual)!=binding['sha256']:raise ValueError('Changed physical M5 successor: '+name)
        if binding['before_sha256'] is not None and sha(_old(name))!=binding['before_sha256']:raise ValueError('Changed M5 predecessor')
        if binding['before_sha256'] is None and _baseline_entry(name).strip():raise ValueError('M5 addition exists in predecessor')
    return value


def historical_bytes(root,name,current):
    from ci.phase5_m6_maintenance import historical_bytes as m6_bytes
    current=m6_bytes(root,name,current)
    current = unicode_adapter().historical_bytes(root, name, current)
    if name not in MEMBERS:return current
    root=Path(root)
    if root.resolve()!=ROOT.resolve():raise ValueError('Foreign M5 historical projection')
    paths=_physical_paths(root,{name})
    binding=_decode(paths[MANIFEST.relative_to(ROOT).as_posix()].read_bytes(),PIN)['members'][name]
    collection=collection_adapter().m5_bindings(root) if name in {'ci/people_job_retention_maintenance.py','ci/dependency_tests/test_phase5_m5_maintenance.py'} else {}
    actual=m6_bytes(root,name,paths[name].read_bytes())
    if name=='.github/workflows/phase5-m5-validation.yml':
        actual=unicode_adapter().historical_bytes(root,name,actual)
    if name in collection:
        approved,before=collection[name]
        if sha(actual)!=approved:raise ValueError('Changed physical COLLECTION successor: '+name)
        actual=before
        if sha(current)==approved:current=before
    if sha(actual)!=binding['sha256']:raise ValueError('Changed M5 physical successor: '+name)
    if binding['before_sha256'] is None:
        if sha(current)!=binding['sha256']:raise ValueError('Changed M5 new member')
        return current
    before=_old(name)
    if name in RETAINED and sha(current)==RETAINED[name]:
        if sha(before)!=binding['before_sha256']:raise ValueError('Changed M5 predecessor')
        return current
    if name=='create_defaults/lifecycle/ROADMAP.md' and sha(current) not in {binding['sha256'],binding['before_sha256']}:
        # M3's unchanged tests pass M4's already-projected roadmap back through
        # the inherited chain. Delegate to that original pinned boundary rather
        # than introduce another historical hash or accept arbitrary input.
        from ci import phase5_m4_maintenance as m4
        if sha(current)!=m4.manifest()['members'][name]['before_sha256']:raise ValueError('Forged inherited M4 projection')
        if m4.historical_bytes(root,name,current)!=current:raise ValueError('Changed inherited M4 projection')
        return current
    if sha(before)!=binding['before_sha256'] or sha(current) not in {binding['sha256'],binding['before_sha256']}:raise ValueError('Forged M5 projection')
    return before


def scope_members():
    from ci.phase4_m7 import ROOT as policy_root
    if Path(policy_root).resolve()!=ROOT.resolve():return frozenset()
    from ci.phase5_m6_maintenance import scope_members as m6_scope
    return ((MEMBERS|ANCHORS)-{'create_defaults/lifecycle/ROADMAP.md'}) | bulk_adapter().scope_members() | unicode_adapter().scope_members() | m6_scope()


def verify_scope(root,baseline,names):
    verify_checkout(root)
    from ci.phase5_m6_maintenance import scope_members as m6_scope, verify_scope as verify_m6_scope
    m6_names=names&m6_scope()
    if m6_names:verify_m6_scope(root,baseline,m6_names)
    names=names-m6_names
    if not names<=scope_members():raise ValueError('Unapproved M5 scope')
    unicode_names = names & unicode_adapter().scope_members()
    if unicode_names:
        unicode_adapter().verify_scope(root, baseline, unicode_names)
    names = names - unicode_names
    bulk_names = names & bulk_adapter().scope_members()
    if bulk_names:
        bulk_adapter().verify_scope(root, baseline, bulk_names)
    names = names - bulk_names
    if not names:return
    rows=_git(root,'diff','--raw','--no-abbrev','--no-renames','-z',baseline,'HEAD','--',*sorted(names)).split(b'\0')
    if rows[-1]!=b'' or len(rows)!=2*len(names)+1:raise ValueError('Incomplete M5 scope diff')
    seen=set()
    for offset in range(0,len(rows)-1,2):
        fields,name=rows[offset].split(),rows[offset+1].decode('utf8')
        if (name not in names or name in seen or len(fields)!=5 or fields[:2] not in ([b':000000',b'100644'],[b':100644',b'100644'])
                or fields[4]!=(b'A' if fields[0]==b':000000' else b'M')):raise ValueError('M5 requires regular-file additions/modifications')
        seen.add(name)
    _physical_paths(Path(root),seen)

